<?php
declare(strict_types=1);
final class MigrationQuarantineDecisionLedger
{
 public function __construct(private mysqli$db,private string$p){if(preg_match('/^[A-Za-z0-9_]+$/D',$p)!==1)throw new InvalidArgumentException('Invalid prefix');}
 public function ensureSchema():void{$this->db->query("CREATE TABLE IF NOT EXISTS `{$this->p}fm2_migration_quarantine_decisions`(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,operation_id CHAR(36) NOT NULL,request_sha256 CHAR(64) NOT NULL,source_locator VARCHAR(80) NOT NULL,source_cutoff_at DATETIME NOT NULL,source_digest CHAR(64) NOT NULL,classification_version VARCHAR(80) NOT NULL,quarantine_code VARCHAR(100) NOT NULL,outcome VARCHAR(40) NOT NULL,reason VARCHAR(1000) NOT NULL,actor_user_id BIGINT UNSIGNED NOT NULL,occurred_at VARCHAR(40) NOT NULL,UNIQUE KEY uq_operation(operation_id),KEY ix_reference(source_locator,source_cutoff_at,source_digest,classification_version,quarantine_code,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");}
 public function decide(array$c):array{$c=$this->validate($c);$hash=hash('sha256',json_encode(array_diff_key($c,['occurredAt'=>true]),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));$this->db->begin_transaction();try{$old=$this->operation($c['operationId'],true);if($old){if(!hash_equals($old['request_sha256'],$hash))throw new DomainException('QUARANTINE_OPERATION_CONFLICT');$this->db->commit();return['status'=>'duplicate','decisionId'=>(int)$old['id']];}if(!$this->authorized($c['actorUserId']))throw new DomainException('QUARANTINE_DECISION_FORBIDDEN');$s=$this->db->prepare("SELECT source_digest,classification_version,quarantine_codes_json FROM `{$this->p}fm2_migration_quarantine_registry` WHERE source_locator=? AND source_cutoff_at=? FOR UPDATE");$s->bind_param('ss',$c['sourceLocator'],$c['sourceCutoffAt']);$s->execute();$r=$s->get_result()->fetch_assoc();$codes=is_array($r)?json_decode((string)$r['quarantine_codes_json'],true):null;if(!is_array($r)||!hash_equals($c['sourceDigest'],(string)$r['source_digest'])||$c['classificationVersion']!==$r['classification_version']||!is_array($codes)||!in_array($c['quarantineCode'],$codes,true))throw new DomainException('QUARANTINE_REFERENCE_STALE');$s=$this->db->prepare("INSERT INTO `{$this->p}fm2_migration_quarantine_decisions`(operation_id,request_sha256,source_locator,source_cutoff_at,source_digest,classification_version,quarantine_code,outcome,reason,actor_user_id,occurred_at)VALUES(?,?,?,?,?,?,?,?,?,?,?)");$s->bind_param('sssssssssis',$c['operationId'],$hash,$c['sourceLocator'],$c['sourceCutoffAt'],$c['sourceDigest'],$c['classificationVersion'],$c['quarantineCode'],$c['outcome'],$c['reason'],$c['actorUserId'],$c['occurredAt']);$s->execute();$id=(int)$s->insert_id;$this->db->commit();return['status'=>'accepted','decisionId'=>$id];}catch(Throwable$e){$this->db->rollback();if($e instanceof mysqli_sql_exception&&$e->getCode()===1062){$old=$this->operation($c['operationId'],false);if($old&&hash_equals($old['request_sha256'],$hash))return['status'=>'duplicate','decisionId'=>(int)$old['id']];}throw$e;}}
 public function all():array{return$this->db->query("SELECT operation_id,source_locator,source_cutoff_at,source_digest,classification_version,quarantine_code,outcome,reason,actor_user_id,occurred_at FROM `{$this->p}fm2_migration_quarantine_decisions` ORDER BY source_locator,source_cutoff_at,source_digest,classification_version,quarantine_code,id LIMIT 1000")->fetch_all(MYSQLI_ASSOC);}
 private function validate(array$c):array{$op=(string)($c['operationId']??'');$loc=(string)($c['sourceLocator']??'');$cut=(string)($c['sourceCutoffAt']??'');$dig=(string)($c['sourceDigest']??'');$ver=(string)($c['classificationVersion']??'');$code=(string)($c['quarantineCode']??'');$out=(string)($c['outcome']??'');$reason=trim((string)($c['reason']??''));$actor=$c['actorUserId']??null;$at=(string)($c['occurredAt']??'');if(preg_match('/^[a-f0-9]{8}-[a-f0-9]{4}-4[a-f0-9]{3}-[89ab][a-f0-9]{3}-[a-f0-9]{12}$/D',$op)!==1||preg_match('/^hmac-sha256:[a-f0-9]{64}$/D',$loc)!==1||DateTimeImmutable::createFromFormat('!Y-m-d H:i:s',$cut)?->format('Y-m-d H:i:s')!==$cut||preg_match('/^[a-f0-9]{64}$/D',$dig)!==1||preg_match('/^[A-Za-z0-9_.-]{1,80}$/D',$ver)!==1||preg_match('/^[A-Z0-9_]{1,100}$/D',$code)!==1||!in_array($out,['acknowledge','reject_source_evidence','request_source_correction'],true)||$reason===''||mb_strlen($reason)>1000||!is_int($actor)||$actor<1||DateTimeImmutable::createFromFormat('!Y-m-d\TH:i:sP',$at)?->format('Y-m-d\TH:i:sP')!==$at)throw new InvalidArgumentException('INVALID_QUARANTINE_DECISION');return['operationId'=>$op,'sourceLocator'=>$loc,'sourceCutoffAt'=>$cut,'sourceDigest'=>$dig,'classificationVersion'=>$ver,'quarantineCode'=>$code,'outcome'=>$out,'reason'=>$reason,'actorUserId'=>$actor,'occurredAt'=>$at];}
 private function authorized(int$id):bool{$s=$this->db->prepare("SELECT COUNT(*)n FROM `{$this->p}fm2_pilot_users`u JOIN `{$this->p}fm2_pilot_user_roles`ur ON ur.user_id=u.user_id JOIN `{$this->p}fm2_pilot_roles`r ON r.role_id=ur.role_id WHERE u.user_id=? AND u.status=1 AND r.status=1 AND(r.name='ОТиЗ' OR LOWER(r.name)LIKE'%администратор%')");$s->bind_param('i',$id);$s->execute();return(int)$s->get_result()->fetch_assoc()['n']>0;}
 private function operation(string$op,bool$lock):?array{$s=$this->db->prepare("SELECT id,request_sha256 FROM `{$this->p}fm2_migration_quarantine_decisions` WHERE operation_id=?".($lock?' FOR UPDATE':''));$s->bind_param('s',$op);$s->execute();$r=$s->get_result()->fetch_assoc();return is_array($r)?$r:null;}
}
